def svg(items):
    labels=[x['short'] for x in items]
    w=max(620, len(labels)*142); parts=['<svg viewBox="0 0 %d 150" role="img" aria-label="Signal map">'%w,'<defs><marker id="arr" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#94a3b8"/></marker></defs>']
    for i,l in enumerate(labels):
        x=20+i*142; fill='#ecfdf5' if i==0 else '#fff'; stroke='#01dc82' if i==0 else '#cbd5e1'
        parts += [f'<rect x="{x}" y="48" width="112" height="42" rx="6" fill="{fill}" stroke="{stroke}"/>',f'<text x="{x+56}" y="73" text-anchor="middle" class="label">{l}</text>']
        if i<len(labels)-1: parts.append(f'<line x1="{x+112}" y1="69" x2="{x+136}" y2="69" stroke="#94a3b8" marker-end="url(#arr)"/>')
    parts.append('</svg>'); return ''.join(parts)

def head(title, sub): return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Newsreader:opsz,wght@6..72,400;6..72,500;6..72,600&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">{css}</head><body><main><header><div class="wordmark">{logo}<span>Buildn</span></div><div class="date">Daily Ingest Dossier · {DATE}</div><h1>{title}</h1><div class="sub">{sub}</div></header>'''

def card(item):
    return f'''<article class="card"><h2>{item['title']}</h2><div class="badges"><span class="badge good">fresh</span><span class="badge">{item['type']}</span></div><ul class="facts"><li>Signal: {item['signal']}</li><li>Source: <a href="{item['url']}">{item['source']}</a></li></ul><h3>What it is</h3><div>{item['what']}</div><h3>Why it matters</h3><div>{item['why']}</div><h3>Buildn / client use</h3><div>{item['use']}</div><h3>Do next</h3><ul class="wins">{''.join('<li>'+x+'</li>' for x in item['next'])}</ul><div class="callout">Caveat: {item['caveat']}</div></article>'''

def matrix(rows): return '<table class="matrix"><thead><tr><th>Theme</th><th>Buildn OS</th><th>Client work</th><th>Agent workflows</th><th>Personal leverage</th></tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+c+'</td>' for c in r)+'</tr>' for r in rows)+'</tbody></table>'

